import type { ElementRef } from '../../types/change-request-types';

const WHOLE_PAGE_ELEMENT: ElementRef = {
  xpath: '/html/body',
  tagName: 'body',
  className: '',
  id: '',
  filePaths: [],
};

export const elementRefFromSelector = (selector: string): ElementRef => {
  const trimmed = selector.trim();
  if (trimmed.startsWith('#') && trimmed.length > 1) {
    return {
      ...WHOLE_PAGE_ELEMENT,
      tagName: '',
      id: trimmed.slice(1),
      xpath: '',
    };
  }
  if (trimmed.startsWith('.') && trimmed.length > 1) {
    return {
      ...WHOLE_PAGE_ELEMENT,
      tagName: '',
      className: trimmed.slice(1),
      xpath: '',
    };
  }
  return { ...WHOLE_PAGE_ELEMENT, tagName: '', xpath: trimmed };
};

export const wholePageElement = (): ElementRef => ({ ...WHOLE_PAGE_ELEMENT });
